  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Testosterone undecanoate, a lipophilic long-chain ester prodrug, had an absolute oral bioavailability of 6.83 ± 3.32% in young women, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester steroid, showed poor and inconsistent oral bioavailability in men.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Delmopinol, a lipophilic alkyl-substituted oral agent, had very low bioavailability after oral administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Nimodipine had <5% absolute oral bioavailability in humans, illustrating that highly lipophilic, poorly absorbed drugs can fall far below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a highly lipophilic beta-lactone ester designed for local gastrointestinal action; its recognized systemic absorption is negligible, and analogous long-chain ester prodrugs such as testosterone undecanoate and dimethandrolone undecanoate show F <10%, so F >=20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for orlistat is present in the supplied records.",
    "Most records are from structurally distant drug classes, so transferability relies mainly on lipophilic ester/lactone analogies and recognized query identity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

